"""C# emitter: blittable explicit-layout structs mirroring the C++ ModelParams (user units) for P/Invoke from Unity."""
from __future__ import annotations

from schema_model import LIST_KIND, Leaf, Model

BANNER = """// <auto-generated>
// Generated by schema/tools/generate_params.py from {source}. DO NOT EDIT.
// Regenerate with: python schema/tools/generate_params.py generate
// schema fingerprint: {fingerprint}
// </auto-generated>
"""


def emit_csharp(model: Model, fp: str, namespace: str = "HoverHere.Native") -> str:
    out = [BANNER.format(source=model.path.name, fingerprint=fp).rstrip(), "using System;", "using System.Runtime.InteropServices;", "",
           f"namespace {namespace}", "{",
           "    // Memory layout of the C++ structs in hoverhere/params/model_params.hpp (namespace user, double precision).",
           "    // Booleans are bytes (0 or 1), enums are 32 bit integers holding the option index.", "",
           "    [StructLayout(LayoutKind.Explicit, Size = 24)]", "    public struct Vec3d", "    {",
           "        [FieldOffset(0)] public double x;", "        [FieldOffset(8)] public double y;", "        [FieldOffset(16)] public double z;",
           "        public Vec3d(double x, double y, double z) { this.x = x; this.y = y; this.z = z; }", "    }", "",
           "    // One value per flight bank.", "    [StructLayout(LayoutKind.Explicit, Size = 24)]", "    public struct Bank3d", "    {",
           "        [FieldOffset(0)] public double bank1;", "        [FieldOffset(8)] public double bank2;", "        [FieldOffset(16)] public double bank3;", "",
           "        public double this[int index]", "        {",
           "            get { switch (index) { case 0: return bank1; case 1: return bank2; case 2: return bank3; default: throw new IndexOutOfRangeException(); } }",
           "            set { switch (index) { case 0: bank1 = value; break; case 1: bank2 = value; break; case 2: bank3 = value; break; default: throw new IndexOutOfRangeException(); } }",
           "        }", "    }", ""]
    for cap in sorted({f.leaf.max_count for f in model.flat if f.leaf.type == LIST_KIND}):
        size = 8 + 24 * cap
        out += [f"    // Fixed capacity list of points; only the first `count` entries are valid.",
                f"    [StructLayout(LayoutKind.Explicit, Size = {size})]", f"    public struct Vec3List{cap}", "    {",
                f"        public const int Capacity = {cap};", "        [FieldOffset(0)] public int count;"]
        out += [f"        [FieldOffset({8 + 24 * i})] public Vec3d item{i};" for i in range(cap)]
        out += ["", "        public Vec3d this[int index]", "        {", "            get { switch (index) {"]
        out += [f"                case {i}: return item{i};" for i in range(cap)]
        out += ["                default: throw new IndexOutOfRangeException(); } }", "            set { switch (index) {"]
        out += [f"                case {i}: item{i} = value; break;" for i in range(cap)]
        out += ["                default: throw new IndexOutOfRangeException(); } }", "        }", "    }", ""]
    for name in model.struct_order:
        size, _ = model.struct_info[name]
        out += [f"    [StructLayout(LayoutKind.Explicit, Size = {size})]", f"    public struct {name}", "    {"]
        for c in model.structs[name].children:
            if isinstance(c, Leaf):
                note = (f" // [{c.unit}] " if c.unit and c.type not in ("bool", "enum") else " // ") + c.doc
                out.append(f"        [FieldOffset({c.offset})] public {c.kind['cs']} {c.name};{note}")
            else:
                out.append(f"        [FieldOffset({c.offset})] public {c.struct} {c.name};")
        out += ["    }", ""]
    root = model.roots[0]
    out += ["    // Offsets of all leaves (schema path -> byte offset and size inside ModelParams), checked by the layout test project.",
            "    public static class ModelParamsLayout", "    {", f"        public const int Size = {model.struct_size(root.struct)};",
            "        public static readonly (string Path, int Offset, int Size)[] Leaves = new (string Path, int Offset, int Size)[]", "        {"]
    out += [f'            ("{f.path}", {f.offset}, {f.leaf.kind["size"]}),' for f in model.flat]
    out += ["        };", "    }", "}"]
    return "\n".join(out) + "\n"
